package com.intermarche.e2e.engine.fieldops;
import io.quarkus.test.junit.QuarkusTest;import io.quarkus.narayana.jta.QuarkusTransaction;import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static io.restassured.RestAssured.given;
@QuarkusTest @jakarta.enterprise.inject.Typed(OperatorReceiptWorkflowTest.class)
class OperatorReceiptWorkflowTest extends ParcelWorkflowTest {
 Map<String,Object> receipt(String actor,String key,String kind){return given().auth().oauth2(actor).get("/handling-orders/operator/consultation/receipts/"+key+"?storeId="+f.store()+"&kind="+kind).then().statusCode(200).extract().jsonPath().getMap("$");}
 @Test void receiptCheckIsReadOnlyAndAnAbsentReceiptDoesNotCreateAParcel(){String key=key();assertEquals(false,receipt(f.picker(),key,"PARCEL").get("found"));assertEquals(false,receipt(f.picker(),key,"PARCEL").get("found"));QuarkusTransaction.requiringNew().run(()->assertEquals(0,com.intermarche.backoffice.domain.shipping.Parcel.count("store.id",f.store())));}
 @Test void exactFrozenReceiptIsRecoverableByItsActorWithoutReexecution(){prepared();String key=key();var body=Map.of("storeId",f.store(),"orderId",customer,"requestKey",key);var created=parcel(f.picker(),"",body).then().statusCode(200).extract().jsonPath().<String,Object>getMap("$");var first=receipt(f.picker(),key,"PARCEL");assertEquals(true,first.get("found"));assertEquals(created.get("code"),((Map<?,?>)first.get("result")).get("code"));assertEquals("FROZEN_RECEIPT",first.get("resultBasis"));assertEquals(false,receipt(f.manager(),key,"PARCEL").get("found"));assertEquals(false,receipt(f.picker(),key,"DEPARTURE").get("found"));var saved=save(created,1);var read=receipt(f.picker(),key,"PARCEL");assertTrue(((List<?>)((Map<?,?>)read.get("result")).get("contents")).isEmpty());QuarkusTransaction.requiringNew().run(()->assertEquals(2,com.intermarche.backoffice.domain.shipping.Parcel.count("store.id",f.store())));given().auth().oauth2(f.picker()).get("/handling-orders/operator/consultation/receipts/"+key+"?storeId="+f.other()+"&kind=PARCEL").then().statusCode(403);}
 @Test void lineDirectiveAndMissionStateHaveFrozenFieldReceipts(){
  Long line=line();String key=key();var body=Map.of("storeId",f.store(),"lineId",line,"lineKind","LOT_LINE","requestKey",key,"expectedRevision","0","state","DEFERRED","priority",80,"instruction","Vérifier la date","reason","Date limite à contrôler");
  var changed=call(f.manager(),"PUT","/orders/"+f.order()+"/lines",body).then().statusCode(200).extract().jsonPath().<String,Object>getMap("$");assertEquals(changed.get("revision"),((Map<?,?>)receipt(f.manager(),key,"FIELD").get("result")).get("revision"));assertEquals(false,receipt(f.picker(),key,"FIELD").get("found"));
  String stateKey=key();var state=Map.of("storeId",f.store(),"requestKey",stateKey,"expectedRevision",orderRevision(),"expectedStateRevision","0","state","WAITING","reason","Stock attendu");call(f.picker(),"PUT","/orders/"+f.order()+"/state",state).then().statusCode(200);call(f.picker(),"PUT","/orders/"+f.order()+"/state",state).then().statusCode(200);
  var confirmed=receipt(f.picker(),stateKey,"FIELD");assertEquals("WAITING",((Map<?,?>)confirmed.get("result")).get("state"));var entries=given().auth().oauth2(f.picker()).get("/handling-orders/operator/consultation/activity?storeId="+f.store()).then().statusCode(200).extract().jsonPath().<Map<String,Object>>getList("items");assertEquals(1,entries.stream().filter(e->"WAITING".equals(e.get("declaredState"))&&"Stock attendu".equals(e.get("declaredReason"))).count());
 }
}
